// Worked examples teach the idea; quick checks are reasoning exercises.
// The final mission continues to execute and assess the learner's own program.
const q=(kind,prompt,code,...options)=>({id:kind,kind,prompt,code,options:options.map(([text,why])=>({text,why})),correct:0});
const L=(title,idea,connection,example,output,notes,checks)=>({title,idea,connection,example,output,notes,checks});
export const LESSONS={
 F1:L('One clear instruction','An instruction tells Pip one thing to do.','An arrow is a movement instruction. One arrow moves one square.','move right','Pip moves one square →',['Choose a direction.','Run means “follow my instructions”.'],[
  q('predict','Pip follows this arrow. Which way?','→',['Right →','The arrow points right. Pip moves one square right.'],['Left ←','Left is the opposite direction. Look at the arrowhead.'],['Stay ●','A movement arrow tells Pip to move.']),
  q('complete','The charger is above Pip. Choose a move.','⚡\nPip',['Up ↑','Up takes Pip towards the charger above.'],['Down ↓','Down takes Pip away from that charger.'],['Right →','Right moves across, rather than up.']),
  q('debug','Pip must go right. Fix the wrong arrow.','Wrong move: ←',['Use →','Replace the left arrow with a right arrow.'],['Use ↓','Down is another direction, but the charger is right.'],['Keep ←','Keeping the same arrow keeps the same problem.'])]),
 F2:L('A sequence is a plan','A sequence is a list of instructions in order.','Pip finishes one step, then follows the next.','move right\nmove right\nmove up','Two right, then one up → → ↑',['Read from top to bottom.','Each arrow is one step.'],[
  q('predict','How many moves will Pip make?','→  →  ↑',['3 moves','There are three instructions, so Pip moves three times.'],['2 moves','Count the up arrow as well as the two right arrows.'],['1 move','Pip follows every arrow in the sequence.']),
  q('complete','Finish the plan: two right, then up.','→  ?  ↑',['→','The missing middle step is the second right move.'],['←','Left would undo the first move.'],['↓','Down is not part of this plan.']),
  q('debug','The plan says right, then up. Find the right sequence.','Start → then ↑',['→  ↑','The first move goes right; the next goes up.'],['↑  →','These steps happen in the opposite order.'],['→  →','This plan never moves up.'])]),
 F3:L('Some steps need earlier steps','Order matters when one action needs another action first.','A bridge needs supports before a deck. Open it when it is safe.','add supports\nbuild deck\nopen bridge','Supports → deck → open',['Ask what must happen first.','Having the right steps is not enough: put them in order.'],[
  q('predict','What must come before the bridge deck?','? → deck → open',['Supports','Supports hold the deck up. They must be ready first.'],['Open','Opening an unfinished bridge would be too soon.'],['Nothing','The deck needs something to hold it up.']),
  q('complete','Choose the missing step.','supports → ? → open',['Build the deck','Now the supports can hold the deck.'],['Remove supports','The supports are still needed.'],['Open twice','Opening twice does not build the missing deck.']),
  q('debug','Which plan fixes this unsafe order?','open → supports → deck',['supports → deck → open','Build a safe bridge before opening it.'],['deck → open → supports','The deck would still be built before its supports.'],['supports → open → deck','The bridge would still open before the deck is finished.'])]),
 F4:L('A bug is a mistake to investigate','Debugging means finding and fixing a mistake.','First predict what should happen. Then compare it with what the steps really do.','Wanted: → →\nWritten: → ↓\nFix:     → →','Change the down arrow to right',['Try the plan a step at a time.','Change the step that causes the problem.'],[
  q('predict','Which step leaves the straight path?','→  ↓  →',['The middle ↓','That step goes down instead of along the path.'],['The first →','The first arrow moves along the rightward path.'],['The last →','The last arrow also points along the path.']),
  q('complete','Replace the mistake to go three spaces right.','→  ?  →',['→','All three instructions now move right.'],['↑','Up would leave the straight path.'],['←','Left would undo one of the right moves.']),
  q('debug','Pip goes too far. The goal is two right moves.','→  →  →',['Remove one →','Two right moves reach a goal two squares away.'],['Add one →','An extra move would go even farther.'],['Run the same plan again','Repeating the same plan does not fix the extra step.'])]),
 F5:L('Repeat a small set of steps','A repeat runs the instructions inside it several times.','Count the turns. Then check which instructions belong inside.','repeat 3:\n    move right','Pip follows → → →',['“Repeat 3” means three turns in total.','A step outside Repeat runs once.'],[
  q('predict','How many moves does this make?','repeat 3: →',['3','One right move runs on each of three turns.'],['4','Three is the total number of turns, not three extra turns.'],['1','The repeat runs its inside step more than once.']),
  q('complete','Choose a short plan for four right moves.','Goal: → → → →',['Repeat 4 with → inside','The same move runs four times.'],['Repeat 4 with nothing inside','An empty repeat has no movement to repeat.'],['One → outside Repeat','An outside step only runs once.']),
  q('debug','This loop does nothing. What is missing?','repeat 3:\n    [empty]',['Put Move right inside','Repeat needs an instruction in its body.'],['Change 3 to 4','More empty turns still do nothing.'],['Put Move right after Repeat','That would make just one move after the loop.'])]),
 F6:L('A variable keeps a value','A variable is a named place for a value that can change.','Think of power as a labelled box. Store sets its value; Add changes it.','set power to 2\nadd 1 to power','power = 3',['Set replaces the old value.','Add uses the value already in the box.'],[
  q('predict','What value is in power at the end?','set power to 2\nadd 1',['3','Start with two, then add one.'],['1','Adding one does not replace the original two.'],['2','The Add instruction changes the stored value.']),
  q('complete','Power is 3. We need 5. Choose an action.','power = 3 → ? → power = 5',['Add 2','Three plus two is five.'],['Add 5','That would make eight, not five.'],['Set power to 2','Set replaces three with two.']),
  q('debug','We wanted to add one, but lost the old power. Fix it.','power is 4\nset power to 1',['Use Add 1','Add keeps the four and increases it to five.'],['Keep Set 1','Set replaces four with one.'],['Set power to 0','That also replaces the old value.'])]),
 F7:L('Ask a yes-or-no question','A condition is a question with a true or false answer.','An If runs its inside steps only when the condition is true.','if power is at least 3:\n    open gate','Power 3: open. Power 2: wait.',['“At least” includes the target number.','If the answer is false, skip the inside steps.'],[
  q('predict','Power is 3. Does the gate open?','if power is at least 3: open',['Yes','Three is at least three, so the condition is true.'],['No','The target itself counts as enough.'],['Always, whatever the power','The power still has to satisfy the condition.']),
  q('complete','Which question protects a gate that needs 5?','if ?:\n    open gate',['Power is at least 5','This checks there is enough power.'],['Power is below 5','That is exactly when there is too little power.'],['Pip has a nice name','A name does not tell us whether the gate has power.']),
  q('debug','The gate must only open when ready. Where does Open go?','if enough power:\n    [inside]\n[outside]',['Inside If','Only the true branch will open the gate.'],['After If, outside','An outside action runs even when the condition is false.'],['Before the check','That opens the gate before knowing whether it is ready.'])]),
 F8:L('Choose one of two paths','If/else chooses between two sets of steps.','If takes the true path. Else takes the other path. Only one runs.','if left trail is clear:\n    go left\nelse:\n    go right','Clear ← | blocked →',['A sensor tells us about the world.','Else means “otherwise”, not “also”.'],[
  q('predict','The left trail is blocked. Where does Pip go?','if clear: left\nelse: right',['Right →','The clear check is false, so Else chooses right.'],['Left ←','The left path is only chosen when it is clear.'],['Both paths','If/else chooses one branch, not both.']),
  q('complete','Finish the safe plan.','if left trail is clear: left\nelse: ?',['Right →','The other route is used when left is blocked.'],['Left ←','That would send Pip onto the blocked route.'],['Go left and right','Only the chosen branch should guide this trip.']),
  q('debug','Both routes run. How should the second route change?','if clear: left\ngo right [outside]',['Put Right inside Else','Then Right runs only when Clear is false.'],['Keep Right outside','The outside move runs after either answer.'],['Put both moves inside If','That still chooses two moves when the test is true.'])]),
 F9:L('Make a reusable instruction','A function is a named set of instructions you can call.','Making repair stores the plan. Using repair runs the plan.','make repair:\n    fix the next building\nuse repair\nuse repair','Two calls → two buildings fixed',['A definition describes what to do.','A call asks for that work now.'],[
  q('predict','How many repairs happen?','make repair: fix next\nuse repair\nuse repair',['2','The plan is called twice. Each call fixes the next place.'],['1','There are two calls, not just one.'],['3','Defining the plan does not run it.']),
  q('complete','A repair plan is ready. How do we run it?','make repair: fix next\n?',['Use repair','A call runs the named plan.'],['Make repair again','A definition only stores the plan.'],['Rename Pip','Changing a name does not call the repair plan.']),
  q('debug','The plan is made, but nothing is fixed. What is missing?','make repair:\n    fix next',['A Use repair call','A function has to be called to do its work.'],['A longer function name','The name is not the problem.'],['Another unused definition','Two unused plans still do no repairs.'])]),
 F10:L('Join small ideas into a plan','A program can combine variables, repeats and conditions.','Give each part one job: remember power, collect cells, then check readiness.','set power to 0\nrepeat 2:\n    collect a cell\n    add 1 to power\nif power is at least 2:\n    open gate','Power 0 → 1 → 2. Then open.',['Start with a known value.','Change the value inside the repeat.','Check readiness after collecting.'],[
  q('predict','What is power after the repeat?','set power to 0\nrepeat 2: add 1',['2','Zero gains one on each of two turns.'],['0','The instructions inside the repeat change the value.'],['3','There are only two additions, starting from zero.']),
  q('complete','What belongs before a gate that needs 2?','collect cells → ? → open',['If power is at least 2','Use the value to decide whether the gate is ready.'],['Forget the power value','The gate still needs a readiness check.'],['Open before collecting','That checks nothing and happens too early.']),
  q('debug','Power never rises. Where should Add 1 go?','repeat 2:\n    collect a cell\n[missing action]',['Inside the repeat, after Collect','Each collected cell must also update the remembered power.'],['Only after the repeat','That would add just one for the whole trip.'],['Only before setting power to 0','Setting zero would erase that earlier change.'])]),
 P11:L('Make a program speak','print() sends a value to the output.','The game puts printed messages on its beacon. Text needs quotes.','print("Hello Pip")','Hello Pip',['print is lowercase.','Quotes mark text; brackets surround the value.'],[
  q('predict','What appears in the output?','print("Ready!")',['Ready!','print sends the text between the quotes to output.'],['"Ready!"','The quotes mark the text; they are not printed.'],['print','The command name is not the message.']),
  q('complete','Choose the line that prints a greeting.','?',['print("Hi Pip")','This uses lowercase print, quotes and matching brackets.'],['Print("Hi Pip")','Python is case-sensitive: the command is print.'],['print(Hi Pip)','Text needs quotes. Without them, these are not a text value.']),
  q('debug','Fix the missing punctuation.','print("Go!"',['print("Go!")','The closing bracket finishes the call.'],['print("Go!"','The bracket is still missing.'],['print(Go!)','The message still needs quotes.'])]),
 P12:L('Name the values you need','A variable gives a value a name so you can use it later.','Python can store text, numbers and booleans. Assign with =; then use the name.','name = "Nova"\nenergy = 4\nenergy = energy + 1\nready = True\nprint(name)\nprint(energy)\nprint(ready)','Nova\n5\nTrue',['"Nova" is text; 4 is a number.','energy + 1 uses the old value before assigning the new one.','True and False start with capitals.'],[
  q('predict','What number is printed?','energy = 4\nenergy = energy + 1\nprint(energy)',['5','The second assignment replaces four with four plus one.'],['4','The value changes before it is printed.'],['1','The expression adds one to the old energy; it is not just one.']),
  q('complete','Store Pip as text in name.','?',['name = "Pip"','Quotes make Pip a text value.'],['name = Pip','Without quotes, Pip would be another variable name.'],['"name" = "Pip"','Assign to a variable name, not a quoted text value.']),
  q('debug','Which line fixes the ready value?','ready = true',['ready = True','Python spells its boolean values True and False.'],['ready = "True"','That stores text, not a boolean.'],['ready = FALSE','FALSE is not Python’s False value.'])]),
 P13:L('Calculate instead of guessing','Arithmetic builds a new value from other values.','Use * for multiplication, + for addition and - for subtraction.','panels = 2\ncells_each = 3\nsupplies = panels * cells_each\nprint(supplies)','6',['Two groups of three need six cells.','Calculate first, then use the result in a game command.'],[
  q('predict','How many supplies are calculated?','panels = 2\ncells_each = 3\nprint(panels * cells_each)',['6','Two panels each need three: 2 × 3 = 6.'],['5','Five is 2 + 3; here we need two groups of three.'],['23','These are numbers being multiplied, not text joined together.']),
  q('complete','Choose the multiplication expression.','supplies = ?',['panels * cells_each','The star is Python’s multiplication operator.'],['panels + cells_each','Addition does not calculate a number for every panel.'],['panels cells_each','An operator is needed between the names.']),
  q('debug','We have 10 cells and use 3. Fix the calculation.','remaining = 10 + 3',['remaining = 10 - 3','Subtract what was used: seven cells remain.'],['remaining = 10 * 3','Multiplication would make thirty, not what remains.'],['remaining = "10 - 3"','Quotes would store the expression as text without calculating it.'])]),
 P14:L('Compare values to get an answer','A comparison produces True or False.','>= means “at least”. Use that answer when a gate needs enough power.','enough = 4 >= 4\nprint(enough)','True',['The target number itself is enough.','== compares; = assigns a value.'],[
  q('predict','What does the comparison produce?','4 >= 4',['True','Equal values satisfy “at least”.'],['False','>= includes equality. > alone would be false here.'],['4','A comparison produces a boolean, not either input number.']),
  q('complete','Check that energy is at least needed.','enough = ?',['energy >= needed','This asks whether energy meets or exceeds the goal.'],['energy < needed','This is true when energy is too low.'],['energy = needed','= assigns; it is not this comparison.']),
  q('debug','Only exactly 5 should pass. Which comparison fixes it?','energy >= 5',['energy == 5','== asks whether the two values are equal.'],['energy > 5','This excludes five and accepts larger values.'],['energy != 5','!= asks whether the values differ.'])]),
 P15:L('Choose the first matching branch','if, elif and else choose what happens next.','Python checks the conditions in order and runs the first matching branch.','energy = 3\nif energy >= 5:\n    print("big job")\nelif energy >= 2:\n    print("small job")\nelse:\n    print("charge")','small job',['elif means “otherwise, if”.','else is the fallback when earlier checks are false.','Indent the actions belonging to each branch.'],[
  q('predict','Which message is printed?','energy = 3\nif energy >= 5: print("big")\nelif energy >= 2: print("small")\nelse: print("charge")',['small','The first check is false; the second is true. Only that branch runs.'],['big','Three is not at least five.'],['small and charge','Once a branch matches, else is skipped.']),
  q('complete','Add another condition after if.','if destination == "garden":\n    print("seeds")\n? destination == "workshop":\n    print("tools")',['elif','elif lets you test another condition when the first did not match.'],['else','else has no condition after it.'],['repeat','repeat is not a Python branch keyword.']),
  q('debug','Which repair makes this valid Python?','if ready\nprint("Go")',['if ready:\n    print("Go")','A colon introduces the branch; indentation puts the action inside it.'],['if ready;\nprint("Go")','Python needs a colon and an indented body here.'],['IF ready:\n    print("Go")','Python keywords use lowercase if.'])]),
 P16:L('Count repeated jobs with for','A for loop visits a sequence of values.','range(3) produces 0, 1 and 2. Use each number to choose a plant.','for plant in range(3):\n    print(plant)','0\n1\n2',['Counting starts at zero.','The stop number is excluded.','The indented body runs once for each value.'],[
  q('predict','Which values does range(3) give?','for plant in range(3):',['0, 1, 2','range starts at zero and stops before three.'],['1, 2, 3','That starts one too late for this range.'],['0, 1, 2, 3','The stop number three is not included.']),
  q('complete','Water the current plant on every turn.','for plant in range(game.count()):\n    ?',['game.water(plant)','The loop variable changes, so each plant is watered.'],['game.water(0)','That would keep watering the first plant.'],['game.water("plant")','The quoted word is text; the command needs the current number.']),
  q('debug','Only the last value prints. Fix the layout.','for number in range(3):\n    pass\nprint(number)',['Put print(number) inside the loop','Indenting print makes it run for every number.'],['Move print before the loop','The loop has not assigned number yet.'],['Change range(3) to range(4)','More turns do not move the print into the loop.'])]),
 P17:L('Repeat while a condition is true','A while loop checks its condition before every turn.','Its body must change something that will eventually make the condition false.','energy = 0\nwhile energy < 2:\n    energy = energy + 1\nprint(energy)','2',['Check → act → check again.','At two, energy < 2 is false, so the loop stops.'],[
  q('predict','What is the final energy?','energy = 0\nwhile energy < 2:\n    energy += 1',['2','The turns change energy to one, then two; the next check is false.'],['3','The condition is checked before another addition.'],['0','The starting condition is true, so the body runs.']),
  q('complete','Add the action that lets this charging loop finish.','while game.energy() < game.needed():\n    ?',['game.charge(1)','Charging increases the value tested by the condition.'],['print("charging")','Printing does not change the energy.'],['pass','pass does nothing, so the energy cannot rise.']),
  q('debug','Energy is 3, but the condition is energy < 2. How many turns?','while energy < 2:\n    energy += 1',['0 turns','A while loop can skip its body when its first check is false.'],['1 turn','while checks before the first turn, not after it.'],['Forever','The first check is already false, so this loop never starts.'])]),
 P18:L('Give a reusable function an input','A function names a reusable job. A parameter receives an input for that job.','Define it with def. Call it with a different argument whenever you need it.','def greet(name):\n    print("Hi " + name)\n\ngreet("Pip")\ngreet("Nova")','Hi Pip\nHi Nova',['name is the parameter: the input’s local name.','"Pip" and "Nova" are arguments passed by the calls.'],[
  q('predict','What does the second call print?','def greet(name):\n    print("Hi " + name)\ngreet("Pip")\ngreet("Nova")',['Hi Nova','The second argument is assigned to the parameter for that call.'],['Hi Pip','That was the first call’s argument.'],['Hi name','name is a variable, not quoted text.']),
  q('complete','Pass the place into the repair command.','def repair(place):\n    ?',['game.repair(place)','The command receives whichever place the caller supplied.'],['game.repair("place")','This sends the literal word place, not the input value.'],['game.repair("bridge")','This hard-codes one building instead of using the parameter.']),
  q('debug','The function is defined but no greeting appears. What is missing?','def greet(name):\n    print(name)',['greet("Pip")','A call runs the function and supplies its input.'],['def greet(name): again','Another definition still does not run the function.'],['print(greet)','That prints information about the function rather than calling it.'])]),
 P19:L('Visit every item in a list','A list keeps several values in order.','A for loop can visit each value directly, including repeated values.','supplies = ["seeds", "tools", "seeds"]\nfor item in supplies:\n    print(item)','seeds\ntools\nseeds',['Square brackets make a list.','item gets one value at a time.','Repeated items are still separate entries.'],[
  q('predict','How many messages appear?','items = ["seeds", "tools", "seeds"]\nfor item in items:\n    print(item)',['3','Each list entry is visited, including the second seeds entry.'],['2','Equal values do not remove entries from a list.'],['1','The loop visits more than just the first item.']),
  q('complete','Deliver the current item.','for item in deliveries:\n    ?',['game.deliver(item)','item holds the entry for this turn.'],['game.deliver(deliveries)','That passes the whole list instead of one item.'],['game.deliver("item")','That sends the literal word item.']),
  q('debug','Why does this deliver tools repeatedly?','for item in deliveries:\n    game.deliver("tools")',['Use item instead of "tools"','The changing loop variable chooses each actual parcel.'],['Remove the loop','That would not visit every entry.'],['Rename deliveries only','Changing the list’s name does not change the fixed argument.'])]),
 P20:L('Build a bigger program from small jobs','A bigger program combines ideas you already know.','Plan the order: get ready, read a list, then call a checked routine for each place.','def visit(place):\n    if energy >= 2:\n        print(place)\n\nenergy = 0\nwhile energy < 2:\n    energy += 1\nplaces = ["garden", "bridge"]\nfor place in places:\n    visit(place)','garden\nbridge',['The while loop makes the power ready.','The list says which places need help.','The function checks power whenever it is called.'],[
  q('predict','Why charge before calling the repair routine?','charge → visit each place',['So its power check can pass','Preparing the state first lets the checked action do its work.'],['Functions only work at the end of a file','Functions can be called whenever they have been defined.'],['A list needs electricity','The power belongs to the game task, not Python’s list.']),
  q('complete','Use the current place with the reusable routine.','for place in places:\n    ?',['restore(place)','Each call receives the place for this turn.'],['restore("place")','That passes the literal word, not the current building.'],['restore(places)','That passes the whole list instead of one place.']),
  q('debug','Every place needs a power check. Which design helps?','def restore(place):\n    ?',['Check power inside restore','Every call then applies the same readiness rule.'],['Check once after all repairs','That check would happen too late.'],['Remove the condition','The program still needs to respect the power requirement.'])]),
 C11:L('Write a message as a statement','Console.WriteLine() sends a value to the output.','Text goes inside quotes and brackets. A semicolon ends the statement.','Console.WriteLine("Hello Pip");','Hello Pip',['C# cares about capital letters.','The semicolon ends this instruction.'],[
  q('predict','What appears in the output?','Console.WriteLine("Ready!");',['Ready!','WriteLine sends the text to output and ends the line.'],['"Ready!"','Quotes mark the text; they are not part of this output.'],['Console','Console is part of the command name, not the message.']),
  q('complete','Choose the valid statement.','?',['Console.WriteLine("Hi Pip");','The capitals, quotes, brackets and semicolon are all present.'],['console.writeline("Hi Pip");','C# names are case-sensitive: Console.WriteLine uses capitals.'],['Console.WriteLine(Hi Pip);','Text must be enclosed in quotes.']),
  q('debug','Which punctuation is missing?','Console.WriteLine("Go!")',['A semicolon ;','This statement ends with a semicolon after the bracket.'],['A colon :','A colon does not end this C# statement.'],['Another opening bracket (','The brackets already match.'])]),
 C12:L('Choose names and types','A variable has a name, a type and a value.','Use string for text, int for whole numbers and bool for true or false.','string name = "Nova";\nint energy = 4;\nbool ready = true;\nConsole.WriteLine(name);\nConsole.WriteLine(energy);\nConsole.WriteLine(ready);','Nova\n4\nTrue',['The type says what kind of value belongs here.','Use lowercase true and false in C# source.','Console displays a boolean as True or False.'],[
  q('predict','Which type fits a whole-number energy value?','energy = 4',['int','int stores a whole number such as four.'],['string','string stores text rather than a numeric energy value.'],['bool','bool stores only true or false.']),
  q('complete','Store Pip as a name.','?',['string name = "Pip";','A string variable stores the quoted text.'],['int name = "Pip";','Text cannot be stored in an int variable.'],['bool name = "Pip";','A bool needs true or false, not a name.']),
  q('debug','Fix the type mismatch.','bool ready = "true";',['bool ready = true;','Remove the quotes to use a boolean value.'],['bool ready = 1;','C# does not use 1 in place of a bool here.'],['bool ready = True;','The C# keyword is lowercase true.'])]),
 C13:L('Turn quantities into calculations','Arithmetic produces new numeric values.','Use * to multiply groups and - to calculate what remains.','int panels = 2;\nint supplies = panels * 3;\nint remaining = 10 - supplies;\nConsole.WriteLine(supplies);\nConsole.WriteLine(remaining);','6\n4',['Two groups of three need six supplies.','Ten minus six leaves four.'],[
  q('predict','What value is stored in supplies?','int panels = 2;\nint supplies = panels * 3;',['6','The multiplication makes two groups of three.'],['5','Five would be the result of addition, not multiplication.'],['23','These values are numbers, not text being joined.']),
  q('complete','Calculate energy left after using supplies.','int remaining = ?;',['20 - supplies','Subtract the used supplies from the starting amount.'],['20 + supplies','Adding would increase the energy after using some.'],['supplies - 20','This subtracts in the wrong direction for the remaining energy.']),
  q('debug','Which change makes a numeric calculation?','string total = "2 * 3";',['int total = 2 * 3;','The unquoted expression is calculated and stored as a number.'],['string total = "6";','That stores text instead of a calculated numeric value.'],['int total = "2 * 3";','The quoted expression is still text, which cannot go in int.'])]),
 C14:L('A comparison makes a bool','Comparison operators ask questions about values.','>= means “at least”; the result can tell the lift whether there is enough power.','bool enough = 4 >= 4;\nConsole.WriteLine(enough);','True',['>= includes equal values.','== compares equality; = assigns a value.'],[
  q('predict','Is this bool true or false?','bool enough = 4 >= 4;',['true','Four meets the “at least four” requirement.'],['false','>= includes equality; > alone would not.'],['4','The result of a comparison is a bool.']),
  q('complete','Compare power with its target.','bool enough = ?;',['energy >= needed','This accepts power that meets or exceeds the target.'],['energy < needed','This is true when power is insufficient.'],['energy + needed','Addition gives a number, not the required bool.']),
  q('debug','Exactly floor 2 should match. Which expression fixes it?','floor > 2',['floor == 2','== tests equality with two.'],['floor >= 2','That would also match higher floors.'],['floor != 2','That would match every floor except two.'])]),
 C15:L('Choose an if or an else','An if/else statement selects one branch.','C# puts the condition in brackets and groups the branch’s statements with braces.','int energy = 1;\nif (energy >= 2)\n{\n    Console.WriteLine("repair");\n}\nelse\n{\n    Console.WriteLine("charge");\n}','charge',['The true branch follows if.','Else handles the false answer.','Braces show which statements belong together.'],[
  q('predict','Which message is written?','int energy = 1;\nif (energy >= 2) { Console.WriteLine("repair"); }\nelse { Console.WriteLine("charge"); }',['charge','One is below two, so the else branch runs.'],['repair','The if condition is false for energy one.'],['repair and charge','Only one branch of this if/else runs.']),
  q('complete','Compare the sensor text in the if condition.','if (?) { Game.Route("left"); }',['Game.Sensor() == "clear"','== compares the sensor result with the quoted text.'],['Game.Sensor() = "clear"','= is assignment, not the comparison needed here.'],['"clear"','A string by itself is not a bool condition.']),
  q('debug','Right runs on every trip. Where should it go?','if (clear) { Game.Route("left"); }\nGame.Route("right");',['Inside an else block','Then right runs only when clear is false.'],['Before the if','It would still run on every trip.'],['Inside the same if block','Then both routes would run when clear is true.'])]),
 C16:L('Count the turns of a for loop','A for loop has a start, a condition and a change after each turn.','Start at zero, keep going while below the count, then increase the counter.','for (int light = 0; light < 3; light++)\n{\n    Console.WriteLine(light);\n}','0\n1\n2',['Start: light is zero.','Check: light must be below three.','Change: light++ adds one after each turn.'],[
  q('predict','Which light numbers are visited?','for (int light = 0; light < 3; light++)',['0, 1, 2','The counter starts at zero and stops before three.'],['1, 2, 3','This loop starts at zero, not one.'],['0, 1, 2, 3','The condition excludes three.']),
  q('complete','Light the current signal on every turn.','for (int light = 0; light < Game.Count(); light++)\n{\n    ?\n}',['Game.Light(light);','Use the changing counter as the signal number.'],['Game.Light(0);','That would keep selecting the first signal.'],['Game.Light("light");','The command needs a number, not a quoted word.']),
  q('debug','What change makes this counter move forwards?','for (int i = 0; i < 3; /* missing change */)',['i++','Increase i by one after each turn so it can reach the stopping condition.'],['i--','Decreasing i moves it farther below three.'],['Leave the change empty','If nothing else changes i, the condition stays true.'])]),
 C17:L('Repeat until the state changes','A while loop repeats while its bool condition is true.','Its body must make progress towards the stopping condition.','int energy = 0;\nwhile (energy < 2)\n{\n    energy++;\n}\nConsole.WriteLine(energy);','2',['The condition is checked before every turn.','A loop can run zero times.','Stop is available if a loop cannot finish.'],[
  q('predict','What is energy when the loop finishes?','int energy = 0;\nwhile (energy < 2) { energy++; }',['2','The values become one and two; then the next condition is false.'],['3','At two, another turn is not allowed.'],['0','The condition starts true, so the loop does run.']),
  q('complete','Let this charging loop make progress.','while (Game.Energy() < Game.Needed())\n{\n    ?\n}',['Game.Charge(1);','Charging changes the energy checked by the condition.'],['Console.WriteLine("charging");','Printing alone does not change the energy.'],['Game.Energy();','Reading a sensor does not increase its value.']),
  q('debug','Energy starts at 3. How many turns run?','while (energy < 2) { energy++; }',['0','The first check is false, so the body is skipped.'],['1','The condition is checked before the first turn.'],['Forever','A false starting condition stops this loop immediately.'])]),
 C18:L('Give a method an input','A method names a reusable job and can receive parameters.','Declare each parameter’s type. Pass a value when you call the method.','void Greet(string name)\n{\n    Console.WriteLine("Hi " + name);\n}\nGreet("Pip");\nGreet("Nova");','Hi Pip\nHi Nova',['void means the method returns no value.','string name receives the text supplied by a call.','Different arguments let the same method do different jobs.'],[
  q('predict','What does the second call write?','void Greet(string name) { Console.WriteLine(name); }\nGreet("Pip");\nGreet("Nova");',['Nova','The second call supplies Nova to the parameter.'],['Pip','Pip was the first call’s argument.'],['name','The variable name is not the text stored in it.']),
  q('complete','Use the method’s place parameter.','void Repair(string place)\n{\n    ?\n}',['Game.Repair(place);','This passes the value received by the method.'],['Game.Repair("place");','That passes the literal word place.'],['Game.Repair("bridge");','That ignores the parameter and always chooses one building.']),
  q('debug','The method exists but never runs. What is missing?','void Greet(string name)\n{\n    Console.WriteLine(name);\n}',['Greet("Pip");','This call supplies an argument and runs the body.'],['Declare Greet again','Another declaration still does not call it.'],['Greet;','A method call needs brackets and the required argument.'])]),
 C19:L('Visit a collection with foreach','A collection holds several values. foreach visits each one.','On every turn, item contains the next value, including duplicate entries.','string[] supplies = { "seeds", "tools", "seeds" };\nforeach (string item in supplies)\n{\n    Console.WriteLine(item);\n}','seeds\ntools\nseeds',['string[] means an array of strings.','foreach reads one entry at a time.','Equal entries are still separate deliveries.'],[
  q('predict','How many messages are written?','string[] items = { "seeds", "tools", "seeds" };\nforeach (string item in items) { Console.WriteLine(item); }',['3','Each of the three entries is visited, even repeated seeds.'],['2','An array does not remove equal entries.'],['1','foreach visits every entry, not just the first.']),
  q('complete','Deliver the current item.','foreach (string item in deliveries)\n{\n    ?\n}',['Game.Deliver(item);','item contains this turn’s parcel.'],['Game.Deliver(deliveries);','That is the whole collection rather than one parcel.'],['Game.Deliver("item");','That sends the literal word item.']),
  q('debug','How do we stop sending tools for every entry?','foreach (string item in deliveries)\n{\n    Game.Deliver("tools");\n}',['Use item instead of "tools"','The loop variable changes to match each real entry.'],['Rename deliveries','The fixed tools argument would stay the same.'],['Remove foreach','Then the program would not process every entry.'])]),
 C20:L('Make objects from a class','A class describes what an object stores and can do.','Use new to make an object. Its fields keep its own state; its methods use that state.','Robot helper = new Robot("Pip");\nhelper.SayHello();\n\nclass Robot\n{\n    public string Name;\n    public Robot(string name) { Name = name; }\n    public void SayHello() { Console.WriteLine(Name); }\n}','Pip',['Robot is the class; helper is an object made from it.','The constructor stores the supplied name.','In the mission, each robot also keeps energy and uses it for repairs.'],[
  q('predict','Where does this object get its name?','Robot helper = new Robot("Pip");',['The constructor receives "Pip"','The constructor takes the argument and stores it in the object’s field.'],['Every class is automatically named Pip','The name comes from the supplied argument, not the class keyword.'],['Console chooses the name','Console only displays values passed to it.']),
  q('complete','Ask this robot object to run its method.','Robot helper = new Robot("Pip");\n?',['helper.SayHello();','The call selects the helper object’s method.'],['Robot.SayHello();','This example has an instance method, so it needs an object.'],['new SayHello();','new creates objects from types; SayHello is this object’s method.']),
  q('debug','Energy should fall after a successful repair. What is missing?','if (Energy > 0)\n{\n    Game.Repair(place);\n    ?\n}',['Energy--;','Using one unit updates this robot’s stored energy.'],['Energy++;','That adds energy instead of using it.'],['int Energy = 0;','That attempts to declare a separate local name instead of updating the field.'])])
};

export const CHECK_IDS=['predict','complete','debug'];
export function lessonFor(id){return LESSONS[id]??null;}
export function learningState(profile,id){return profile.learning?.[id]??{stage:'learn',index:0,introduced:false,answers:{}};}
export function learningCount(profile,id){return Object.values(profile.learning?.[id]?.answers??{}).filter(a=>a.solved).length;}
export function choiceOrder(check,seed=''){
 let hash=2166136261;for(const c of seed+check.id)hash=Math.imul(hash^c.charCodeAt(0),16777619)>>>0;
 const order=check.options.map((option,index)=>({...option,index}));
 for(let i=order.length-1;i>0;i--){hash=(Math.imul(hash,1664525)+1013904223)>>>0;const j=hash%(i+1);[order[i],order[j]]=[order[j],order[i]];}
 return order;
}
